# ! [doc = " Utilities for formatting and printing `String`s."] # ! [doc = ""] # ! [doc = " This module contains the runtime support for the [`format!`] syntax extension."] # ! [doc = " This macro is implemented in the compiler to emit calls to this module in"] # ! [doc = " order to format arguments at runtime into strings."] # ! [doc = ""] # ! [doc = " # Usage"] # ! [doc = ""] # ! [doc = " The [`format!`] macro is intended to be familiar to those coming from C's"] # ! [doc = " `printf`/`fprintf` functions or Python's `str.format` function."] # ! [doc = ""] # ! [doc = " Some examples of the [`format!`] extension are:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " format!(\"Hello\");                 // => \"Hello\""] # ! [doc = " format!(\"Hello, {}!\", \"world\");   // => \"Hello, world!\""] # ! [doc = " format!(\"The number is {}\", 1);   // => \"The number is 1\""] # ! [doc = " format!(\"{:?}\", (3, 4));          // => \"(3, 4)\""] # ! [doc = " format!(\"{value}\", value=4);      // => \"4\""] # ! [doc = " let people = \"Rustaceans\";"] # ! [doc = " format!(\"Hello {people}!\");       // => \"Hello Rustaceans!\""] # ! [doc = " format!(\"{} {}\", 1, 2);           // => \"1 2\""] # ! [doc = " format!(\"{:04}\", 42);             // => \"0042\" with leading zeros"] # ! [doc = " format!(\"{:#?}\", (100, 200));     // => \"("] # ! [doc = "                                   //       100,"] # ! [doc = "                                   //       200,"] # ! [doc = "                                   //     )\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " From these, you can see that the first argument is a format string. It is"] # ! [doc = " required by the compiler for this to be a string literal; it cannot be a"] # ! [doc = " variable passed in (in order to perform validity checking). The compiler"] # ! [doc = " will then parse the format string and determine if the list of arguments"] # ! [doc = " provided is suitable to pass to this format string."] # ! [doc = ""] # ! [doc = " To convert a single value to a string, use the [`to_string`] method. This"] # ! [doc = " will use the [`Display`] formatting trait."] # ! [doc = ""] # ! [doc = " ## Positional parameters"] # ! [doc = ""] # ! [doc = " Each formatting argument is allowed to specify which value argument it's"] # ! [doc = " referencing, and if omitted it is assumed to be \"the next argument\". For"] # ! [doc = " example, the format string `{} {} {}` would take three parameters, and they"] # ! [doc = " would be formatted in the same order as they're given. The format string"] # ! [doc = " `{2} {1} {0}`, however, would format arguments in reverse order."] # ! [doc = ""] # ! [doc = " Things can get a little tricky once you start intermingling the two types of"] # ! [doc = " positional specifiers. The \"next argument\" specifier can be thought of as an"] # ! [doc = " iterator over the argument. Each time a \"next argument\" specifier is seen,"] # ! [doc = " the iterator advances. This leads to behavior like this:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " format!(\"{1} {} {0} {}\", 1, 2); // => \"2 1 1 2\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " The internal iterator over the argument has not been advanced by the time"] # ! [doc = " the first `{}` is seen, so it prints the first argument. Then upon reaching"] # ! [doc = " the second `{}`, the iterator has advanced forward to the second argument."] # ! [doc = " Essentially, parameters that explicitly name their argument do not affect"] # ! [doc = " parameters that do not name an argument in terms of positional specifiers."] # ! [doc = ""] # ! [doc = " A format string is required to use all of its arguments, otherwise it is a"] # ! [doc = " compile-time error. You may refer to the same argument more than once in the"] # ! [doc = " format string."] # ! [doc = ""] # ! [doc = " ## Named parameters"] # ! [doc = ""] # ! [doc = " Rust itself does not have a Python-like equivalent of named parameters to a"] # ! [doc = " function, but the [`format!`] macro is a syntax extension that allows it to"] # ! [doc = " leverage named parameters. Named parameters are listed at the end of the"] # ! [doc = " argument list and have the syntax:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " identifier '=' expression"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " For example, the following [`format!`] expressions all use named arguments:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " format!(\"{argument}\", argument = \"test\");   // => \"test\""] # ! [doc = " format!(\"{name} {}\", 1, name = 2);          // => \"2 1\""] # ! [doc = " format!(\"{a} {c} {b}\", a=\"a\", b='b', c=3);  // => \"a 3 b\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " If a named parameter does not appear in the argument list, `format!` will"] # ! [doc = " reference a variable with that name in the current scope."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " let argument = 2 + 2;"] # ! [doc = " format!(\"{argument}\");   // => \"4\""] # ! [doc = ""] # ! [doc = " fn make_string(a: u32, b: &str) -> String {"] # ! [doc = "     format!(\"{b} {a}\")"] # ! [doc = " }"] # ! [doc = " make_string(927, \"label\"); // => \"label 927\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " It is not valid to put positional parameters (those without names) after"] # ! [doc = " arguments that have names. Like with positional parameters, it is not"] # ! [doc = " valid to provide named parameters that are unused by the format string."] # ! [doc = ""] # ! [doc = " # Formatting Parameters"] # ! [doc = ""] # ! [doc = " Each argument being formatted can be transformed by a number of formatting"] # ! [doc = " parameters (corresponding to `format_spec` in [the syntax](#syntax)). These"] # ! [doc = " parameters affect the string representation of what's being formatted."] # ! [doc = ""] # ! [doc = " The colon `:` in format syntax divides identifier of the input data and"] # ! [doc = " the formatting options, the colon itself does not change anything, only"] # ! [doc = " introduces the options."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " let a = 5;"] # ! [doc = " let b = &a;"] # ! [doc = " println!(\"{a:e} {b:p}\"); // => 5e0 0x7ffe37b7273c"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ## Width"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " // All of these print \"Hello x    !\""] # ! [doc = " println!(\"Hello {:5}!\", \"x\");"] # ! [doc = " println!(\"Hello {:1$}!\", \"x\", 5);"] # ! [doc = " println!(\"Hello {1:0$}!\", 5, \"x\");"] # ! [doc = " println!(\"Hello {:width$}!\", \"x\", width = 5);"] # ! [doc = " let width = 5;"] # ! [doc = " println!(\"Hello {:width$}!\", \"x\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This is a parameter for the \"minimum width\" that the format should take up."] # ! [doc = " If the value's string does not fill up this many characters, then the"] # ! [doc = " padding specified by fill/alignment will be used to take up the required"] # ! [doc = " space (see below)."] # ! [doc = ""] # ! [doc = " The value for the width can also be provided as a [`usize`] in the list of"] # ! [doc = " parameters by adding a postfix `$`, indicating that the second argument is"] # ! [doc = " a [`usize`] specifying the width."] # ! [doc = ""] # ! [doc = " Referring to an argument with the dollar syntax does not affect the \"next"] # ! [doc = " argument\" counter, so it's usually a good idea to refer to arguments by"] # ! [doc = " position, or use named arguments."] # ! [doc = ""] # ! [doc = " ## Fill/Alignment"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " assert_eq!(format!(\"Hello {:<5}!\", \"x\"),  \"Hello x    !\");"] # ! [doc = " assert_eq!(format!(\"Hello {:-<5}!\", \"x\"), \"Hello x----!\");"] # ! [doc = " assert_eq!(format!(\"Hello {:^5}!\", \"x\"),  \"Hello   x  !\");"] # ! [doc = " assert_eq!(format!(\"Hello {:>5}!\", \"x\"),  \"Hello     x!\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " The optional fill character and alignment is provided normally in conjunction with the"] # ! [doc = " [`width`](#width) parameter. It must be defined before `width`, right after the `:`."] # ! [doc = " This indicates that if the value being formatted is smaller than"] # ! [doc = " `width` some extra characters will be printed around it."] # ! [doc = " Filling comes in the following variants for different alignments:"] # ! [doc = ""] # ! [doc = " * `[fill]<` - the argument is left-aligned in `width` columns"] # ! [doc = " * `[fill]^` - the argument is center-aligned in `width` columns"] # ! [doc = " * `[fill]>` - the argument is right-aligned in `width` columns"] # ! [doc = ""] # ! [doc = " The default [fill/alignment](#fillalignment) for non-numerics is a space and"] # ! [doc = " left-aligned. The"] # ! [doc = " default for numeric formatters is also a space character but with right-alignment. If"] # ! [doc = " the `0` flag (see below) is specified for numerics, then the implicit fill character is"] # ! [doc = " `0`."] # ! [doc = ""] # ! [doc = " Note that alignment might not be implemented by some types. In particular, it"] # ! [doc = " is not generally implemented for the `Debug` trait.  A good way to ensure"] # ! [doc = " padding is applied is to format your input, then pad this resulting string"] # ! [doc = " to obtain your output:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " println!(\"Hello {:^15}!\", format!(\"{:?}\", Some(\"hi\"))); // => \"Hello   Some(\"hi\")   !\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ## Sign/`#`/`0`"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " assert_eq!(format!(\"Hello {:+}!\", 5), \"Hello +5!\");"] # ! [doc = " assert_eq!(format!(\"{:#x}!\", 27), \"0x1b!\");"] # ! [doc = " assert_eq!(format!(\"Hello {:05}!\", 5),  \"Hello 00005!\");"] # ! [doc = " assert_eq!(format!(\"Hello {:05}!\", -5), \"Hello -0005!\");"] # ! [doc = " assert_eq!(format!(\"{:#010x}!\", 27), \"0x0000001b!\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " These are all flags altering the behavior of the formatter."] # ! [doc = ""] # ! [doc = " * `+` - This is intended for numeric types and indicates that the sign"] # ! [doc = "         should always be printed. By default only the negative sign of signed values"] # ! [doc = "         is printed, and the sign of positive or unsigned values is omitted."] # ! [doc = "         This flag indicates that the correct sign (`+` or `-`) should always be printed."] # ! [doc = " * `-` - Currently not used"] # ! [doc = " * `#` - This flag indicates that the \"alternate\" form of printing should"] # ! [doc = "         be used. The alternate forms are:"] # ! [doc = "     * `#?` - pretty-print the [`Debug`] formatting (adds linebreaks and indentation)"] # ! [doc = "     * `#x` - precedes the argument with a `0x`"] # ! [doc = "     * `#X` - precedes the argument with a `0x`"] # ! [doc = "     * `#b` - precedes the argument with a `0b`"] # ! [doc = "     * `#o` - precedes the argument with a `0o`"] # ! [doc = ""] # ! [doc = "   See [Formatting traits](#formatting-traits) for a description of what the `?`, `x`, `X`,"] # ! [doc = "   `b`, and `o` flags do."] # ! [doc = ""] # ! [doc = " * `0` - This is used to indicate for integer formats that the padding to `width` should"] # ! [doc = "         both be done with a `0` character as well as be sign-aware. A format"] # ! [doc = "         like `{:08}` would yield `00000001` for the integer `1`, while the"] # ! [doc = "         same format would yield `-0000001` for the integer `-1`. Notice that"] # ! [doc = "         the negative version has one fewer zero than the positive version."] # ! [doc = "         Note that padding zeros are always placed after the sign (if any)"] # ! [doc = "         and before the digits. When used together with the `#` flag, a similar"] # ! [doc = "         rule applies: padding zeros are inserted after the prefix but before"] # ! [doc = "         the digits. The prefix is included in the total width."] # ! [doc = "         This flag overrides the [fill character and alignment flag](#fillalignment)."] # ! [doc = ""] # ! [doc = " ## Precision"] # ! [doc = ""] # ! [doc = " For non-numeric types, this can be considered a \"maximum width\". If the resulting string is"] # ! [doc = " longer than this width, then it is truncated down to this many characters and that truncated"] # ! [doc = " value is emitted with proper `fill`, `alignment` and `width` if those parameters are set."] # ! [doc = ""] # ! [doc = " For integral types, this is ignored."] # ! [doc = ""] # ! [doc = " For floating-point types, this indicates how many digits after the decimal point should be"] # ! [doc = " printed."] # ! [doc = ""] # ! [doc = " There are three possible ways to specify the desired `precision`:"] # ! [doc = ""] # ! [doc = " 1. An integer `.N`:"] # ! [doc = ""] # ! [doc = "    the integer `N` itself is the precision."] # ! [doc = ""] # ! [doc = " 2. An integer or name followed by dollar sign `.N$`:"] # ! [doc = ""] # ! [doc = "    use format *argument* `N` (which must be a `usize`) as the precision."] # ! [doc = ""] # ! [doc = " 3. An asterisk `.*`:"] # ! [doc = ""] # ! [doc = "    `.*` means that this `{...}` is associated with *two* format inputs rather than one:"] # ! [doc = "    - If a format string in the fashion of `{:<spec>.*}` is used, then the first input holds"] # ! [doc = "      the `usize` precision, and the second holds the value to print."] # ! [doc = "    - If a format string in the fashion of `{<arg>:<spec>.*}` is used, then the `<arg>` part"] # ! [doc = "      refers to the value to print, and the `precision` is taken like it was specified with an"] # ! [doc = "      omitted positional parameter (`{}` instead of `{<arg>:}`)."] # ! [doc = ""] # ! [doc = " For example, the following calls all print the same thing `Hello x is 0.01000`:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " // Hello {arg 0 (\"x\")} is {arg 1 (0.01) with precision specified inline (5)}"] # ! [doc = " println!(\"Hello {0} is {1:.5}\", \"x\", 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {arg 1 (\"x\")} is {arg 2 (0.01) with precision specified in arg 0 (5)}"] # ! [doc = " println!(\"Hello {1} is {2:.0$}\", 5, \"x\", 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {arg 0 (\"x\")} is {arg 2 (0.01) with precision specified in arg 1 (5)}"] # ! [doc = " println!(\"Hello {0} is {2:.1$}\", \"x\", 5, 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {next arg -> arg 0 (\"x\")} is {second of next two args -> arg 2 (0.01) with precision"] # ! [doc = " //                          specified in first of next two args -> arg 1 (5)}"] # ! [doc = " println!(\"Hello {} is {:.*}\",    \"x\", 5, 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {arg 1 (\"x\")} is {arg 2 (0.01) with precision"] # ! [doc = " //                          specified in next arg -> arg 0 (5)}"] # ! [doc = " println!(\"Hello {1} is {2:.*}\",  5, \"x\", 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {next arg -> arg 0 (\"x\")} is {arg 2 (0.01) with precision"] # ! [doc = " //                          specified in next arg -> arg 1 (5)}"] # ! [doc = " println!(\"Hello {} is {2:.*}\",   \"x\", 5, 0.01);"] # ! [doc = ""] # ! [doc = " // Hello {next arg -> arg 0 (\"x\")} is {arg \"number\" (0.01) with precision specified"] # ! [doc = " //                          in arg \"prec\" (5)}"] # ! [doc = " println!(\"Hello {} is {number:.prec$}\", \"x\", prec = 5, number = 0.01);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " While these:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " println!(\"{}, `{name:.*}` has 3 fractional digits\", \"Hello\", 3, name=1234.56);"] # ! [doc = " println!(\"{}, `{name:.*}` has 3 characters\", \"Hello\", 3, name=\"1234.56\");"] # ! [doc = " println!(\"{}, `{name:>8.*}` has 3 right-aligned characters\", \"Hello\", 3, name=\"1234.56\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " print three significantly different things:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " Hello, `1234.560` has 3 fractional digits"] # ! [doc = " Hello, `123` has 3 characters"] # ! [doc = " Hello, `     123` has 3 right-aligned characters"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " When truncating these values, Rust uses [round half-to-even](https://en.wikipedia.org/wiki/Rounding#Rounding_half_to_even),"] # ! [doc = " which is the default rounding mode in IEEE 754."] # ! [doc = " For example,"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " print!(\"{0:.1$e}\", 12345, 3);"] # ! [doc = " print!(\"{0:.1$e}\", 12355, 3);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Would return:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " 1.234e4"] # ! [doc = " 1.236e4"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ## Localization"] # ! [doc = ""] # ! [doc = " In some programming languages, the behavior of string formatting functions"] # ! [doc = " depends on the operating system's locale setting. The format functions"] # ! [doc = " provided by Rust's standard library do not have any concept of locale and"] # ! [doc = " will produce the same results on all systems regardless of user"] # ! [doc = " configuration."] # ! [doc = ""] # ! [doc = " For example, the following code will always print `1.5` even if the system"] # ! [doc = " locale uses a decimal separator other than a dot."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " println!(\"The value is {}\", 1.5);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Escaping"] # ! [doc = ""] # ! [doc = " The literal characters `{` and `}` may be included in a string by preceding"] # ! [doc = " them with the same character. For example, the `{` character is escaped with"] # ! [doc = " `{{` and the `}` character is escaped with `}}`."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " assert_eq!(format!(\"Hello {{}}\"), \"Hello {}\");"] # ! [doc = " assert_eq!(format!(\"{{ Hello\"), \"{ Hello\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Syntax"] # ! [doc = ""] # ! [doc = " To summarize, here you can find the full grammar of format strings."] # ! [doc = " The syntax for the formatting language used is drawn from other languages,"] # ! [doc = " so it should not be too alien. Arguments are formatted with Python-like"] # ! [doc = " syntax, meaning that arguments are surrounded by `{}` instead of the C-like"] # ! [doc = " `%`. The actual grammar for the formatting syntax is:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " format_string := text [ maybe_format text ] *"] # ! [doc = " maybe_format := '{' '{' | '}' '}' | format"] # ! [doc = " format := '{' [ argument ] [ ':' format_spec ] [ ws ] * '}'"] # ! [doc = " argument := integer | identifier"] # ! [doc = ""] # ! [doc = " format_spec := [[fill]align][sign]['#']['0'][width]['.' precision][type]"] # ! [doc = " fill := character"] # ! [doc = " align := '<' | '^' | '>'"] # ! [doc = " sign := '+' | '-'"] # ! [doc = " width := count"] # ! [doc = " precision := count | '*'"] # ! [doc = " type := '?' | 'x?' | 'X?' | 'o' | 'x' | 'X' | 'p' | 'b' | 'e' | 'E'"] # ! [doc = " count := parameter | integer"] # ! [doc = " parameter := argument '$'"] # ! [doc = " ```"] # ! [doc = " In the above grammar,"] # ! [doc = " - `text` must not contain any `'{'` or `'}'` characters,"] # ! [doc = " - `ws` is any character for which [`char::is_whitespace`] returns `true`, has no semantic"] # ! [doc = "   meaning and is completely optional,"] # ! [doc = " - `integer` is a decimal integer that may contain leading zeroes and must fit into an `usize` and"] # ! [doc = " - `identifier` is an `IDENTIFIER_OR_KEYWORD` (not an `IDENTIFIER`) as defined by the [Rust language reference](https://doc.rust-lang.org/reference/identifiers.html)."] # ! [doc = ""] # ! [doc = " # Formatting traits"] # ! [doc = ""] # ! [doc = " When requesting that an argument be formatted with a particular type, you"] # ! [doc = " are actually requesting that an argument ascribes to a particular trait."] # ! [doc = " This allows multiple actual types to be formatted via `{:x}` (like [`i8`] as"] # ! [doc = " well as [`isize`]). The current mapping of types to traits is:"] # ! [doc = ""] # ! [doc = " * *nothing* ⇒ [`Display`]"] # ! [doc = " * `?` ⇒ [`Debug`]"] # ! [doc = " * `x?` ⇒ [`Debug`] with lower-case hexadecimal integers"] # ! [doc = " * `X?` ⇒ [`Debug`] with upper-case hexadecimal integers"] # ! [doc = " * `o` ⇒ [`Octal`]"] # ! [doc = " * `x` ⇒ [`LowerHex`]"] # ! [doc = " * `X` ⇒ [`UpperHex`]"] # ! [doc = " * `p` ⇒ [`Pointer`]"] # ! [doc = " * `b` ⇒ [`Binary`]"] # ! [doc = " * `e` ⇒ [`LowerExp`]"] # ! [doc = " * `E` ⇒ [`UpperExp`]"] # ! [doc = ""] # ! [doc = " What this means is that any type of argument which implements the"] # ! [doc = " [`fmt::Binary`][`Binary`] trait can then be formatted with `{:b}`. Implementations"] # ! [doc = " are provided for these traits for a number of primitive types by the"] # ! [doc = " standard library as well. If no format is specified (as in `{}` or `{:6}`),"] # ! [doc = " then the format trait used is the [`Display`] trait."] # ! [doc = ""] # ! [doc = " When implementing a format trait for your own type, you will have to"] # ! [doc = " implement a method of the signature:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(dead_code)]"] # ! [doc = " # use std::fmt;"] # ! [doc = " # struct Foo; // our custom type"] # ! [doc = " # impl fmt::Display for Foo {"] # ! [doc = " fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {"] # ! [doc = " # write!(f, \"testing, testing\")"] # ! [doc = " # } }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Your type will be passed as `self` by-reference, and then the function"] # ! [doc = " should emit output into the Formatter `f` which implements `fmt::Write`. It is up to each"] # ! [doc = " format trait implementation to correctly adhere to the requested formatting parameters."] # ! [doc = " The values of these parameters can be accessed with methods of the"] # ! [doc = " [`Formatter`] struct. In order to help with this, the [`Formatter`] struct also"] # ! [doc = " provides some helper methods."] # ! [doc = ""] # ! [doc = " Additionally, the return value of this function is [`fmt::Result`] which is a"] # ! [doc = " type alias of <code>[Result]<(), [std::fmt::Error]></code>. Formatting implementations"] # ! [doc = " should ensure that they propagate errors from the [`Formatter`] (e.g., when"] # ! [doc = " calling [`write!`]). However, they should never return errors spuriously. That"] # ! [doc = " is, a formatting implementation must and may only return an error if the"] # ! [doc = " passed-in [`Formatter`] returns an error. This is because, contrary to what"] # ! [doc = " the function signature might suggest, string formatting is an infallible"] # ! [doc = " operation. This function only returns a [`Result`] because writing to the"] # ! [doc = " underlying stream might fail and it must provide a way to propagate the fact"] # ! [doc = " that an error has occurred back up the stack."] # ! [doc = ""] # ! [doc = " An example of implementing the formatting traits would look"] # ! [doc = " like:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " use std::fmt;"] # ! [doc = ""] # ! [doc = " #[derive(Debug)]"] # ! [doc = " struct Vector2D {"] # ! [doc = "     x: isize,"] # ! [doc = "     y: isize,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl fmt::Display for Vector2D {"] # ! [doc = "     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {"] # ! [doc = "         // The `f` value implements the `Write` trait, which is what the"] # ! [doc = "         // write! macro is expecting. Note that this formatting ignores the"] # ! [doc = "         // various flags provided to format strings."] # ! [doc = "         write!(f, \"({}, {})\", self.x, self.y)"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " // Different traits allow different forms of output of a type. The meaning"] # ! [doc = " // of this format is to print the magnitude of a vector."] # ! [doc = " impl fmt::Binary for Vector2D {"] # ! [doc = "     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {"] # ! [doc = "         let magnitude = (self.x * self.x + self.y * self.y) as f64;"] # ! [doc = "         let magnitude = magnitude.sqrt();"] # ! [doc = ""] # ! [doc = "         // Respect the formatting flags by using the helper method"] # ! [doc = "         // `pad_integral` on the Formatter object. See the method"] # ! [doc = "         // documentation for details, and the function `pad` can be used"] # ! [doc = "         // to pad strings."] # ! [doc = "         let decimals = f.precision().unwrap_or(3);"] # ! [doc = "         let string = format!(\"{magnitude:.decimals$}\");"] # ! [doc = "         f.pad_integral(true, \"\", &string)"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " fn main() {"] # ! [doc = "     let myvector = Vector2D { x: 3, y: 4 };"] # ! [doc = ""] # ! [doc = "     println!(\"{myvector}\");       // => \"(3, 4)\""] # ! [doc = "     println!(\"{myvector:?}\");     // => \"Vector2D {x: 3, y:4}\""] # ! [doc = "     println!(\"{myvector:10.3b}\"); // => \"     5.000\""] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ### `fmt::Display` vs `fmt::Debug`"] # ! [doc = ""] # ! [doc = " These two formatting traits have distinct purposes:"] # ! [doc = ""] # ! [doc = " - [`fmt::Display`][`Display`] implementations assert that the type can be faithfully"] # ! [doc = "   represented as a UTF-8 string at all times. It is **not** expected that"] # ! [doc = "   all types implement the [`Display`] trait."] # ! [doc = " - [`fmt::Debug`][`Debug`] implementations should be implemented for **all** public types."] # ! [doc = "   Output will typically represent the internal state as faithfully as possible."] # ! [doc = "   The purpose of the [`Debug`] trait is to facilitate debugging Rust code. In"] # ! [doc = "   most cases, using `#[derive(Debug)]` is sufficient and recommended."] # ! [doc = ""] # ! [doc = " Some examples of the output from both traits:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " assert_eq!(format!(\"{} {:?}\", 3, 4), \"3 4\");"] # ! [doc = " assert_eq!(format!(\"{} {:?}\", 'a', 'b'), \"a 'b'\");"] # ! [doc = " assert_eq!(format!(\"{} {:?}\", \"foo\\n\", \"bar\\n\"), \"foo\\n \\\"bar\\\\n\\\"\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Related macros"] # ! [doc = ""] # ! [doc = " There are a number of related macros in the [`format!`] family. The ones that"] # ! [doc = " are currently implemented are:"] # ! [doc = ""] # ! [doc = " ```ignore (only-for-syntax-highlight)"] # ! [doc = " format!      // described above"] # ! [doc = " write!       // first argument is either a &mut io::Write or a &mut fmt::Write, the destination"] # ! [doc = " writeln!     // same as write but appends a newline"] # ! [doc = " print!       // the format string is printed to the standard output"] # ! [doc = " println!     // same as print but appends a newline"] # ! [doc = " eprint!      // the format string is printed to the standard error"] # ! [doc = " eprintln!    // same as eprint but appends a newline"] # ! [doc = " format_args! // described below."] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ### `write!`"] # ! [doc = ""] # ! [doc = " [`write!`] and [`writeln!`] are two macros which are used to emit the format string"] # ! [doc = " to a specified stream. This is used to prevent intermediate allocations of"] # ! [doc = " format strings and instead directly write the output. Under the hood, this"] # ! [doc = " function is actually invoking the [`write_fmt`] function defined on the"] # ! [doc = " [`std::io::Write`] and the [`std::fmt::Write`] trait. Example usage is:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " use std::io::Write;"] # ! [doc = " let mut w = Vec::new();"] # ! [doc = " write!(&mut w, \"Hello {}!\", \"world\");"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ### `print!`"] # ! [doc = ""] # ! [doc = " This and [`println!`] emit their output to stdout. Similarly to the [`write!`]"] # ! [doc = " macro, the goal of these macros is to avoid intermediate allocations when"] # ! [doc = " printing output. Example usage is:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " print!(\"Hello {}!\", \"world\");"] # ! [doc = " println!(\"I have a newline {}\", \"character at the end\");"] # ! [doc = " ```"] # ! [doc = " ### `eprint!`"] # ! [doc = ""] # ! [doc = " The [`eprint!`] and [`eprintln!`] macros are identical to"] # ! [doc = " [`print!`] and [`println!`], respectively, except they emit their"] # ! [doc = " output to stderr."] # ! [doc = ""] # ! [doc = " ### `format_args!`"] # ! [doc = ""] # ! [doc = " [`format_args!`] is a curious macro used to safely pass around"] # ! [doc = " an opaque object describing the format string. This object"] # ! [doc = " does not require any heap allocations to create, and it only"] # ! [doc = " references information on the stack. Under the hood, all of"] # ! [doc = " the related macros are implemented in terms of this. First"] # ! [doc = " off, some example usage is:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # #![allow(unused_must_use)]"] # ! [doc = " use std::fmt;"] # ! [doc = " use std::io::{self, Write};"] # ! [doc = ""] # ! [doc = " let mut some_writer = io::stdout();"] # ! [doc = " write!(&mut some_writer, \"{}\", format_args!(\"print with a {}\", \"macro\"));"] # ! [doc = ""] # ! [doc = " fn my_fmt_fn(args: fmt::Arguments<'_>) {"] # ! [doc = "     write!(&mut io::stdout(), \"{args}\");"] # ! [doc = " }"] # ! [doc = " my_fmt_fn(format_args!(\", or a {} too\", \"function\"));"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " The result of the [`format_args!`] macro is a value of type [`fmt::Arguments`]."] # ! [doc = " This structure can then be passed to the [`write`] and [`format`] functions"] # ! [doc = " inside this module in order to process the format string."] # ! [doc = " The goal of this macro is to even further prevent intermediate allocations"] # ! [doc = " when dealing with formatting strings."] # ! [doc = ""] # ! [doc = " For example, a logging library could use the standard formatting syntax, but"] # ! [doc = " it would internally pass around this structure until it has been determined"] # ! [doc = " where output should go to."] # ! [doc = ""] # ! [doc = " [`fmt::Result`]: Result \"fmt::Result\""] # ! [doc = " [Result]: core::result::Result \"std::result::Result\""] # ! [doc = " [std::fmt::Error]: Error \"fmt::Error\""] # ! [doc = " [`write`]: write() \"fmt::write\""] # ! [doc = " [`to_string`]: crate::string::ToString::to_string \"ToString::to_string\""] # ! [doc = " [`write_fmt`]: ../../std/io/trait.Write.html#method.write_fmt"] # ! [doc = " [`std::io::Write`]: ../../std/io/trait.Write.html"] # ! [doc = " [`std::fmt::Write`]: ../../std/fmt/trait.Write.html"] # ! [doc = " [`print!`]: ../../std/macro.print.html \"print!\""] # ! [doc = " [`println!`]: ../../std/macro.println.html \"println!\""] # ! [doc = " [`eprint!`]: ../../std/macro.eprint.html \"eprint!\""] # ! [doc = " [`eprintln!`]: ../../std/macro.eprintln.html \"eprintln!\""] # ! [doc = " [`format_args!`]: ../../std/macro.format_args.html \"format_args!\""] # ! [doc = " [`fmt::Arguments`]: Arguments \"fmt::Arguments\""] # ! [doc = " [`format`]: format() \"fmt::format\""] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; #[stable (feature = "fmt_flags_align" , since = "1.28.0")] pub use core :: fmt :: Alignment ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: Error ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { Arguments , write } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { Binary , Octal } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { Debug , Display } ; #[unstable (feature = "formatting_options" , issue = "118117")] pub use core :: fmt :: { DebugAsHex , FormattingOptions , Sign } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { DebugList , DebugMap , DebugSet , DebugStruct , DebugTuple } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { Formatter , Result , Write } ; #[unstable (feature = "debug_closure_helpers" , issue = "117729")] pub use core :: fmt :: { FromFn , from_fn } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { LowerExp , UpperExp } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: fmt :: { LowerHex , Pointer , UpperHex } ; #[cfg (not (no_global_oom_handling))] use crate :: string ; #[doc = " Takes an [`Arguments`] struct and returns the resulting formatted string."] #[doc = ""] #[doc = " The [`Arguments`] instance can be created with the [`format_args!`] macro."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::fmt;"] #[doc = ""] #[doc = " let s = fmt::format(format_args!(\"Hello, {}!\", \"world\"));"] #[doc = " assert_eq!(s, \"Hello, world!\");"] #[doc = " ```"] #[doc = ""] #[doc = " Please note that using [`format!`] might be preferable."] #[doc = " Example:"] #[doc = ""] #[doc = " ```"] #[doc = " let s = format!(\"Hello, {}!\", \"world\");"] #[doc = " assert_eq!(s, \"Hello, world!\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`format_args!`]: core::format_args"] #[doc = " [`format!`]: crate::format"] #[cfg (not (no_global_oom_handling))] #[must_use] #[stable (feature = "rust1" , since = "1.0.0")] #[inline] pub fn format (args : Arguments < '_ >) -> string :: String { fn format_inner (args : Arguments < '_ >) -> string :: String { let capacity = args . estimated_capacity () ; let mut output = string :: String :: with_capacity (capacity) ; output . write_fmt (args) . expect ("a formatting trait implementation returned an error when the underlying stream did not") ; output } args . as_str () . map_or_else (| | format_inner (args) , crate :: borrow :: ToOwned :: to_owned) }